"""Real tests for the texture validator — actual images generated by
ImageMagick, actually inspected via the real `identify`-backed
inspect(), no mocks."""
import os
import shutil
import subprocess
import sys
import tempfile

PROJECT_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if PROJECT_ROOT not in sys.path:
    sys.path.insert(0, PROJECT_ROOT)

from adapters.imagemagick_adapter import ImageMagickAdapter  # noqa: E402
from validation.texture_validator import validate_texture  # noqa: E402


def _make_image(path, size, color):
    subprocess.run(["magick", "-size", size, f"xc:{color}", path], check=True, capture_output=True)


def run():
    tmp_dir = tempfile.mkdtemp(prefix="koba_test_texture_validator_")
    try:
        magick = ImageMagickAdapter()
        assert magick.detect()

        # --- a clean power-of-two texture: everything should PASS ---
        pot_path = os.path.join(tmp_dir, "pot.png")
        _make_image(pot_path, "512x512", "red")
        result = validate_texture(pot_path, min_width=256, min_height=256, required_format="PNG")
        assert result.passed
        assert result.result == "PASS"
        assert any(label == "Power-of-two dimensions" and status == "PASS" for label, status, _ in result.checks)

        # --- below the resolution floor: a real FAIL, not a warning ---
        small_path = os.path.join(tmp_dir, "small.png")
        _make_image(small_path, "64x64", "green")
        result = validate_texture(small_path, min_width=256, min_height=256)
        assert not result.passed
        assert result.result == "FAIL"

        # --- non-power-of-two: a real WARNING, not a FAIL ---
        npot_path = os.path.join(tmp_dir, "npot.png")
        _make_image(npot_path, "300x150", "yellow")
        result = validate_texture(npot_path)
        assert result.passed, "non-power-of-two must only warn, not fail the whole asset"
        assert any(label == "Power-of-two dimensions" and status == "WARNING" for label, status, _ in result.checks)

        # --- wrong format: a real FAIL ---
        jpg_path = os.path.join(tmp_dir, "wrong_format.jpg")
        _make_image(jpg_path, "256x256", "purple")
        result = validate_texture(jpg_path, required_format="PNG")
        assert not result.passed
        assert any(label == "Format" and status == "FAIL" for label, status, _ in result.checks)

        try:
            validate_texture(os.path.join(tmp_dir, "does_not_exist.png"))
            assert False, "must raise on a missing file, not silently no-op"
        except FileNotFoundError:
            pass

        return True
    finally:
        shutil.rmtree(tmp_dir, ignore_errors=True)


if __name__ == "__main__":
    ok = run()
    print("test_texture_validator: PASS" if ok else "test_texture_validator: FAIL")
    sys.exit(0 if ok else 1)
